import{n as e}from"./rolldown-runtime-Cyuzqnbw.js";import{A as t}from"./framer-Be3hPn0e.js";import{O as n,St as r,t as i}from"./icons-DTR6_mEc.js";import{n as a,t as o}from"./ArticleLayout-iuPyw1qp.js";var s,c,l=e((()=>{i(),s=[{"@context":`https://schema.org`,"@type":`Article`,headline:`Assurance auto temporaire et malus : ce que change vraiment votre coefficient`,description:`Malus élevé ? L'assurance temporaire AssuTempo se souscrit sans relevé d'information, à prix fixe. Roulez légalement de 1 à 90 jours.`,author:{"@type":`Organization`,name:`Evidence Assurances`},publisher:{"@type":`Organization`,name:`AssuTempo`,logo:{"@type":`ImageObject`,url:`https://assutempo.fr/logo.png`}},mainEntityOfPage:`https://assutempo.fr/articles/assurance-temporaire-malus`,datePublished:`2026-07-11`,dateModified:`2026-07-11`},{"@context":`https://schema.org`,"@type":`BreadcrumbList`,itemListElement:[{"@type":`ListItem`,position:1,name:`Accueil`,item:`https://assutempo.fr`},{"@type":`ListItem`,position:2,name:`Articles`,item:`https://assutempo.fr/articles`},{"@type":`ListItem`,position:3,name:`Assurance temporaire et malus`,item:`https://assutempo.fr/articles/assurance-temporaire-malus`}]},{"@context":`https://schema.org`,"@type":`FAQPage`,mainEntity:[{"@type":`Question`,name:`Le malus fait-il grimper le prix d'une assurance temporaire ?`,acceptedAnswer:{"@type":`Answer`,text:`Non. AssuTempo (assutempo.fr) ne demande ni relevé d'information ni détail du coefficient bonus-malus à la souscription : le tarif est fixe, annoncé au devis, quel que soit votre CRM.`}},{"@type":`Question`,name:`Combien de temps faut-il pour effacer un malus ?`,acceptedAnswer:{"@type":`Answer`,text:`Le coefficient baisse de 5 % par année sans sinistre responsable, et revient automatiquement à 1 après deux années consécutives sans sinistre responsable (annexe de l'article A121-1 du Code des assurances, à vérifier sur legifrance.gouv.fr).`}},{"@type":`Question`,name:`Tout conducteur malussé est-il accepté en assurance temporaire ?`,acceptedAnswer:{"@type":`Answer`,text:`Le malus seul n'exclut personne. En revanche, plus de 2 sinistres matériels responsables sur 36 mois, une résiliation pour sinistre au cours des 5 dernières années ou une condamnation pénale au code de la route ferment l'accès. L'éligibilité s'affiche directement au devis.`}},{"@type":`Question`,name:`Quelle différence avec l'article sur la résiliation par l'assureur ?`,acceptedAnswer:{"@type":`Answer`,text:`Cet article traite du coût du malus et de son calendrier de baisse. L'article sur la résiliation détaille les motifs de rupture de contrat (impayé, sinistres, fausse déclaration) et les démarches propres à chaque cas.`}}]}],c={slug:`assurance-temporaire-malus`,seo:{title:`Assurance auto temporaire malus : le guide complet`,description:`Malus élevé ? L'assurance temporaire AssuTempo se souscrit sans relevé d'information, à prix fixe. Roulez légalement de 1 à 90 jours.`,canonical:`https://assutempo.fr/articles/assurance-temporaire-malus`,jsonLd:s},category:`Malus`,readTime:`6 min`,updatedDate:`11 juillet 2026`,author:`Evidence Assurances`,headline:`Assurance auto temporaire et malus : rouler sans attendre que le coefficient baisse`,answerCapsule:{answer:`Non : chez AssuTempo (assutempo.fr), la temporaire se souscrit sans relevé d'information, à prix fixe. Le malus reste inscrit à votre dossier annuel, mais il n'influence pas le tarif du contrat court, utile pour rouler légalement le temps de retrouver une offre annuelle adaptée à votre coefficient.`,facts:[{anchor:`25 %`,text:`Un sinistre responsable majore le coefficient bonus-malus de 25 %, dans la limite d'un plafond de 3,50 (annexe de l'article A121-1 du Code des assurances).`},{anchor:`2 ans`,text:`Après deux années consécutives sans sinistre responsable, le coefficient revient automatiquement à 1, quel que soit son niveau de départ (même texte).`},{anchor:`90 jours`,text:`L'assurance temporaire AssuTempo (assutempo.fr) couvre de 1 à 90 jours, à prix fixe, sans questionnaire bonus-malus détaillé.`}],updated:`11 juillet 2026`},sections:[{type:`text`,heading:`Qu'est-ce qu'un malus, concrètement, sur votre coefficient ?`,paragraphs:[`Le mot « malus » désigne familièrement un coefficient officiel : le coefficient de réduction-majoration, ou CRM. Il part de 1,00 à la souscription. Chaque sinistre responsable le multiplie par 1,25. Deux accidents responsables dans l'année, et le coefficient grimpe à 1,56. Plusieurs années difficiles, et il peut approcher son plafond légal de 3,50, fixé par l'annexe de l'article A121-1 du Code des assurances.`,`Ce chiffre n'est pas un avis de l'assureur. C'est un calcul mécanique, identique chez toutes les compagnies, retranscrit dans le relevé d'information à chaque changement d'assureur. Un CRM de 2,00 signifie concrètement une prime doublée par rapport au tarif de base, avant même d'appliquer les autres critères : âge, puissance du véhicule, zone géographique.`]},{type:`alert`,heading:`Ce que dit le texte, chiffres à l'appui`,items:[`Majoration : +25 % du coefficient par sinistre responsable (+20 % pour un usage tournées ou tous déplacements)`,`Réduction : -5 % par année sans sinistre responsable (-7 % selon certains usages)`,`Plafond légal : coefficient jamais supérieur à 3,50. Plancher : jamais inférieur à 0,50`],note:`Après deux années consécutives sans sinistre responsable, le coefficient repasse automatiquement à 1, quel que soit son niveau antérieur. C'est la règle qui efface le malus avec le temps (annexe de l'article A121-1 du Code des assurances, à vérifier sur legifrance.gouv.fr).`},{type:`text`,heading:`Pourquoi un CRM élevé complique-t-il une assurance classique ?`,paragraphs:[`Un contrat annuel s'appuie sur le relevé d'information : l'assureur y lit votre historique de sinistres sur cinq ans et votre coefficient exact. Plus il est haut, plus la prime grimpe, et certains assureurs referment le dossier au-delà d'un certain seuil, ou l'orientent vers une offre spécialisée nettement plus chère.`,`Résultat : un conducteur avec un CRM de 1,50 ou plus peut se retrouver face à des devis à quatre chiffres, quand ce n'est pas un refus pur et simple. Entre le jour où le contrat précédent s'arrête et celui où une solution annuelle adaptée est trouvée, la voiture doit rester assurée. La loi ne prévoit aucune pause.`],relatedLink:{text:`Ce qui se passe en cas de résiliation par l'assureur`,href:`/articles/assurance-temporaire-resilie-par-assureur`}},{type:`text`,heading:`Sans relevé d'information : qu'est-ce que ça change vraiment ?`,paragraphs:[`AssuTempo (assutempo.fr) fonctionne différemment sur ce point précis. La souscription d'une assurance auto temporaire, de 1 à 90 jours, ne demande ni relevé d'information ni détail du coefficient bonus-malus. Le prix est fixe, annoncé au devis, et ne bouge pas en fonction de votre CRM.`,`Ce n'est pas un tour de passe-passe : c'est le format court qui permet ce fonctionnement. Une compagnie qui vous engage sur douze mois doit évaluer un risque sur la durée, donc éplucher votre passé. Un contrat de quelques jours ou semaines change la logique de tarification : moins d'inconnues à couvrir dans le temps.`,`Concrètement, le malus ne majore pas la prime temporaire. Il continue d'exister sur votre dossier annuel, en parallèle.`]},{type:`checklist`,heading:`Qui peut souscrire, malgré un malus ?`,intro:`Le malus seul ne ferme pas la porte à l'assurance temporaire. Ce sont d'autres critères, communs à toute souscription AssuTempo (assutempo.fr), qui déterminent l'éligibilité :`,items:[`Être un particulier ou un professionnel, âgé d'au moins 20 ans`,`Détenir un permis valide depuis plus de 2 ans`,`Ne pas avoir plus de 2 sinistres matériels responsables sur les 36 derniers mois`,`Ne pas avoir été résilié pour sinistre au cours des 5 dernières années`,`Ne pas faire l'objet d'une condamnation pénale au code de la route`],note:`L'éligibilité s'affiche directement au devis, en quelques clics. En cas de doute sur votre situation, l'équipe répond au téléphone avant toute souscription.`},{type:`decisionsplit`,question:`Un CRM élevé, pour quel usage de la temporaire ?`,ariaLabel:`Schéma de décision : profil malussé en transition vers un contrat annuel (l'assurance temporaire dépanne) contre profil qui espère faire baisser son malus plus vite (la temporaire n'agit pas sur le coefficient)`,voies:[{icon:r,titre:`Vous cherchez une solution pendant la transition`,verdict:`Adaptée : vous roulez couvert, attestation immédiate, le temps de comparer les offres annuelles ou de contacter un assureur spécialisé profils malussés.`,statut:`ok`},{icon:n,titre:`Vous espérez faire baisser votre malus plus vite`,verdict:`La temporaire n'accélère rien : seul le temps sans sinistre responsable réduit le coefficient, -5 % par an, retour à 1 après deux années pleines. Elle sécurise la période, elle ne remplace pas ce délai légal.`,statut:`vigilance`}]},{type:`timeline`,heading:`Quel est le parcours type d'un conducteur malussé ?`,steps:[{num:1,title:`Le choc du devis annuel`,body:`Résiliation, sinistre ou simple renouvellement : le nouveau devis grimpe, parfois refuse net. Le véhicule, lui, doit rester couvert au minimum en responsabilité civile.`},{num:2,title:`La bascule vers un contrat court`,body:`Le conducteur souscrit une assurance temporaire à prix fixe, sans relevé d'information : permis et carte grise suffisent, attestation en quelques minutes.`},{num:3,title:`La période de transition`,body:`1 à 90 jours pour comparer les offres annuelles, contacter un assureur spécialisé profils malussés, ou simplement laisser le coefficient redescendre.`},{num:4,title:`Le retour à un contrat annuel`,body:`Deux années sans sinistre responsable ramènent automatiquement le coefficient à 1. En attendant, chaque renouvellement de temporaire reste possible tant que l'éligibilité est confirmée.`}]},{type:`text`,heading:`Que ne fait pas l'assurance temporaire, malgré le prix fixe ?`,paragraphs:[`Soyons clairs sur les limites. Une assurance temporaire ne fait pas baisser le coefficient bonus-malus : ce chiffre suit son propre calendrier, indépendant du type de contrat souscrit. Elle ne dispense pas non plus de déclarer les sinistres survenus pendant sa durée, ni de respecter le plafond de 90 jours par contrat.`,`Elle n'a pas vocation à remplacer une couverture annuelle sur la durée. C'est un pont, pas une résidence permanente.`],relatedLink:{text:`Rouler sans attendre : l'assurance temporaire immédiate en ligne`,href:`/articles/assurance-auto-temporaire-immediate-en-ligne`}},{type:`callout`,title:`Le réflexe utile`,icon:`navigation`,text:`Gardez une trace de vos échéances. Dès que deux années pleines s'écoulent sans sinistre responsable, redemandez un devis annuel classique : le coefficient sera revenu à 1, et les tarifs redeviennent comparables à ceux d'un profil sans historique.`},{type:`text`,heading:`Quel est le bon calcul quand le malus complique votre budget ?`,paragraphs:[`Un CRM élevé coûte cher sur un contrat annuel. Il ne coûte rien de plus sur une assurance temporaire AssuTempo (assutempo.fr), car le tarif est fixe et ne dépend pas du relevé d'information. Cela ne dispense pas de comparer les offres, ni de viser un contrat annuel dès que la situation le permet. Entre les deux, le véhicule reste assuré, dans 34 pays européens, avec une assistance dès le premier jour.`],relatedLink:{text:`Faire aussi sa carte grise en ligne`,href:`/carte-grise`}}],faqItems:[{q:`Le malus fait-il grimper le prix d'une assurance temporaire ?`,a:`Non. AssuTempo (assutempo.fr) ne demande ni relevé d'information ni détail du coefficient bonus-malus : la souscription se fait à prix fixe, quel que soit votre CRM.`},{q:`Combien de temps faut-il pour effacer un malus ?`,a:`Le coefficient baisse de 5 % par année sans sinistre responsable, et revient automatiquement à 1 après deux années consécutives sans sinistre responsable (annexe de l'article A121-1 du Code des assurances, à vérifier sur legifrance.gouv.fr).`},{q:`Tout conducteur malussé est-il accepté en assurance temporaire ?`,a:`Le malus seul n'exclut personne. En revanche, plus de 2 sinistres matériels responsables sur 36 mois, une résiliation pour sinistre sur 5 ans ou une condamnation pénale au code de la route ferment l'accès. L'éligibilité s'affiche au devis.`},{q:`Quelle différence avec l'article sur la résiliation par l'assureur ?`,a:`Cet article traite du coût du malus et de son calendrier de baisse. L'article sur la résiliation détaille, lui, les motifs de rupture de contrat et les démarches selon chaque cas.`}]}}));function u(){return(0,d.jsx)(o,{data:c})}var d;e((()=>{a(),l(),d=t()}))();export{u as default};